// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {EmergencyOracleFactory} from "../src/EmergencyOracleFactory.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    EmergencyOracleFactory c;

    function setUp() public {
        c = new EmergencyOracleFactory();
    }

    function _run(address expectedTeam, string memory description) internal {
        vm.assume(true);
        address storedTeam;
        try c.jojoTeam() returns (address __r) { storedTeam = __r; } catch { return; }
        bool reverted;
        address newOracleAddress = address(0);
        try c.newEmergencyOracle(description) {
            reverted = false;
        } catch {
            reverted = true;
        }
        assertTrue(reverted == (address(this) != storedTeam));
    }

    function testFuzz_run(address expectedTeam, string memory description) public {
        vm.assume(expectedTeam.code.length == 0 && uint160(expectedTeam) > 0xffff && expectedTeam != address(this) && expectedTeam != address(c) && expectedTeam != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && expectedTeam != 0x000000000000000000636F6e736F6c652e6c6f67 && expectedTeam != 0x4e59b44847b379578588920cA78FbF26c0B4956C && expectedTeam != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(expectedTeam, description);
    }

    receive() external payable {}
}
